const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}};
const save=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch{toast('Your browser could not save progress.')}};
let bookmarks=read('econprep-bookmarks',[]),history=read('econprep-history',[]),track='PEA',page='overview',test=null,tick=null;
const questions={PEA:[{topic:'Calculus',q:'Let f(x) = x³ − 3x. At which point does f have a local maximum?',options:['x = −1','x = 0','x = 1','x = 3'],answer:0,solution:'Differentiate: f′(x) = 3x² − 3 = 0 gives x = ±1. Since f″(x) = 6x, f″(−1) < 0. Therefore x = −1 is a local maximum.'},{topic:'Probability',q:'Two fair dice are rolled independently. What is the probability that their sum is 8?',options:['1/6','5/36','1/9','7/36'],answer:1,solution:'There are 36 equally likely ordered outcomes. The sum is 8 for (2,6), (3,5), (4,4), (5,3), and (6,2). The probability is 5/36.'},{topic:'Microeconomics',q:'A consumer has utility u(x, y) = xy, income 120, and prices pₓ = 2 and pᵧ = 3. What is the optimal quantity of x?',options:['20','30','40','60'],answer:1,solution:'For Cobb–Douglas utility xy, each good receives half the consumer’s income. Spending on x is 60, so x = 60/2 = 30. The corresponding y is 20.'}],PEB:[{topic:'Calculus',q:'Let f(x) = x³ − 3x on [−2, 2]. Find the global maximum and minimum values, and justify your answer.',solution:'The stationary points solve f′(x) = 3x² − 3 = 0, so x = −1 and x = 1. Compare values at these points and the endpoints: f(−2) = −2, f(−1) = 2, f(1) = −2, f(2) = 2. The global maximum is 2 (at −1 and 2) and the global minimum is −2 (at −2 and 1). Continuity on the closed interval guarantees that these extrema exist.'},{topic:'Microeconomics',q:'A consumer maximizes u(x, y) = xy subject to 2x + 3y ≤ 120 and x, y ≥ 0. Derive the optimal bundle and explain why it is a maximum.',solution:'Utility is increasing in both goods when x, y > 0, so the budget binds. Substitute y = (120 − 2x)/3, giving u(x) = 40x − (2/3)x² for 0 ≤ x ≤ 60. The first-order condition is 40 − (4/3)x = 0, so x = 30 and y = 20. The second derivative is −4/3 < 0, and the endpoints give zero utility. Thus the unique optimal bundle is (30, 20).'}]};

questions.PEB[0].hint='Find the stationary points using f′(x) = 0. Compare f at these points and at both endpoints.';
questions.PEB[1].hint='The budget binds. Substitute y = (120 − 2x)/3 into utility, then maximize the resulting function of x.';
const syllabusSource='https://admission.isical.ac.in/Syllabus/MSQE-Syllabus-2026.pdf';
const subjects=[
{name:'Mathematics',icon:'∑',topics:['Algebra: binomial theorem, AP/GP, series, permutations, combinations, polynomial equations.','Linear algebra: vector spaces, transformations, matrix representations and elementary operations, linear systems, eigenvalues.','Calculus: functions and inverses, limits, continuity, single/multivariable derivatives, definite/indefinite integrals, substitution and parts.','Optimization: unconstrained and two-variable constrained problems; monotonicity, convexity, quasi-convexity; implicit functions; homogeneous and homothetic functions.']},
{name:'Statistics',icon:'σ',topics:['Probability, conditional probability, Bayes’ theorem.','Central tendency, dispersion, correlation, regression.','Discrete and continuous distributions: binomial, geometric, normal, Poisson, chi-square.','Sampling, estimation, hypothesis testing.']},
{name:'Microeconomics',icon:'ƒ',topics:['Choice, consumer behaviour, production.','Competitive markets, perfect competition, monopoly, price discrimination.','Cournot and Bertrand duopoly; strategic interaction.','Public goods, externalities, general equilibrium, welfare.']},
{name:'Macroeconomics',icon:'↗',topics:['National income accounting; Keynesian income determination and multiplier.','IS–LM, aggregate demand and supply.','Money, banking, inflation, Phillips curve.','Open-economy basics; Harrod–Domar and Solow growth.']}
];
function syllabus(){return `${heading('Syllabus','Topic overview · ISI admission test 2026')}<div class="syllabus-source"><span>4 subjects</span><a class="btn outline" href="${syllabusSource}" target="_blank" rel="noopener noreferrer">Official ISI syllabus ↗</a></div><div class="syllabus-grid">${subjects.map(s=>`<section class="syllabus-card"><div class="subject-heading"><span class="track-symbol">${s.icon}</span><h2>${s.name}</h2></div><ul>${s.topics.map(t=>`<li>${t}</li>`).join('')}</ul></section>`).join('')}</div><p class="source-note">Summarized from <a href="${syllabusSource}" target="_blank" rel="noopener noreferrer">ISI’s official 2026 syllabus</a>.</p>`}

function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal()}
function closeModal(){$('#modal').close()}
function heading(title,sub='',eye='ISI MSQE'){return `<div class="welcome"><div><div class="eyebrow">${eye}</div><h1>${title}</h1>${sub?`<p class="subtitle">${sub}</p>`:''}</div></div>`}
function stat(icon,value,label){return `<div class="stat"><span class="stat-icon">${icon}</span><div><strong>${value}</strong><small>${label}</small></div></div>`}
function trackCard(t){return `<article class="track ${t.toLowerCase()}"><div class="track-top"><span class="track-symbol">${t==='PEA'?'∑':'ƒ'}</span><span class="pill">${t==='PEA'?'OBJECTIVE':'DESCRIPTIVE'}</span></div><h3>${t}<span>Paper ${t==='PEA'?'A':'B'}</span></h3><p>${t==='PEA'?'Multiple-choice practice':'Questions, hints & solutions'}</p><div class="track-bottom"><span>${questions[t].length} sample questions</span><button class="text-button" data-track="${t}">Practice ${t} &nbsp; ↗</button></div></article>`}
function paperRow(year){return `<div class="paper-row"><span class="paper-file">▤</span><div class="paper-name">ISI MSQE ${year}</div><span class="pill">IMPORT PENDING</span><button class="text-button" data-year="${year}">View &nbsp; ↗</button></div>`}
function overview(){return `<section class="hero main-hero"><div class="hero-copy"><div class="eyebrow">ECONPREP</div><h1>ISI MSQE<br><span>Preparation</span></h1><p>Past papers. Mock tests. Clear solutions.</p><div class="hero-actions"><button class="btn light" data-go="practice">Start practice ↗</button><button class="hero-link" data-go="syllabus">View syllabus →</button></div></div><svg viewBox="0 0 440 265" aria-hidden="true"><defs><pattern id="grid" width="37" height="37" patternUnits="userSpaceOnUse"><path d="M 37 0 L 0 0 0 37" fill="none" stroke="#afc997" stroke-opacity=".1"/></pattern><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#bbd28b" stop-opacity=".25"/><stop offset="1" stop-color="#bbd28b" stop-opacity="0"/></linearGradient></defs><rect width="440" height="265" fill="url(#grid)"/><path d="M45 220 C125 220 167 201 212 157 S305 95 387 44 L387 230 L45 230Z" fill="url(#area)"/><path d="M45 220 C125 220 167 201 212 157 S305 95 387 44" stroke="#cfdf9d" fill="none" stroke-width="2.7"/><path d="M70 46V227H405" stroke="#729b77" fill="none" stroke-width=".8"/><path d="M70 170 L387 90" stroke="#82a982" stroke-dasharray="5 6" fill="none"/><circle cx="252" cy="123" r="6" fill="#d7e5b1"/><circle cx="252" cy="123" r="15" fill="none" stroke="#d7e5b1" stroke-opacity=".25"/><text x="55" y="45" fill="#91b294" font-size="10">y</text><text x="407" y="240" fill="#91b294" font-size="10">x</text></svg></section><div class="stats">${stat('▤','27','Years · 1998–2024')}${stat('◷',history.length,'Sessions completed')}${stat('♧',bookmarks.length,'Bookmarks')}${stat('◎','2','Practice tracks')}</div><div class="section-head"><h2>Choose your paper</h2><span class="pill">DEMO</span></div><div class="tracks">${trackCard('PEA')}${trackCard('PEB')}</div><div class="lower-grid"><section><div class="section-head"><h2>Past year papers</h2><button class="text-button" data-go="papers">All years ↗</button></div><div class="paper-table">${[2024,2023,2022].map(paperRow).join('')}</div></section><section class="syllabus-teaser"><span class="eyebrow">OFFICIAL 2026 SYLLABUS</span><h2>What to study</h2><p>Mathematics · Statistics<br>Microeconomics · Macroeconomics</p><button class="text-button" data-go="syllabus">View topics ↗</button></section></div>`}
function papers(){return `${heading('Past year papers','1998–2024')}<div class="notice">Full papers pending import. Demo practice is available.</div><div class="filters"><input id="search" type="search" aria-label="Search paper year" placeholder="Search year"><select id="paper-track" aria-label="Paper track"><option value="PEA">PEA · Objective</option><option value="PEB">PEB · Descriptive</option></select><select id="sort" aria-label="Sort years"><option value="new">Newest first</option><option value="old">Oldest first</option></select></div><div class="library-grid" id="paper-list"></div>`}
function renderPapers(){const query=$('#search').value.trim();let years=Array.from({length:27},(_,i)=>2024-i).filter(y=>String(y).includes(query));if($('#sort').value==='old')years.reverse();const t=$('#paper-track').value;$('#paper-list').innerHTML=years.length?years.map(y=>`<article class="library-card"><span class="pill">${t} · ${t==='PEA'?'OBJECTIVE':'DESCRIPTIVE'}</span><h3>ISI MSQE ${y}</h3><p>Import pending</p><button class="btn outline" data-preview="${t}" data-paper-year="${y}">View paper ↗</button></article>`).join(''):'<div class="empty">No matching paper years.</div>'}
function practice(){return `${heading('Practice')}<div class="tabs"><button data-switch="PEA" class="${track==='PEA'?'active':''}">PEA · Objective</button><button data-switch="PEB" class="${track==='PEB'?'active':''}">PEB · Descriptive</button></div><section class="practice-intro"><span class="track-symbol">${track==='PEA'?'∑':'ƒ'}</span><h2>${track} sample practice</h2><p>${track==='PEA'?'3 questions · 10 minutes':'2 questions · Hints & solutions'}</p><button class="btn" id="start-demo">Start ${track} demo ↗</button></section><div class="notice">Original demo questions. ${track==='PEA'?'Demo scoring: +1 correct, 0 otherwise.':'Practice on paper; use hints when needed.'}</div><div class="section-head" style="margin-top:28px"><h2>Past year papers</h2><button class="text-button" data-go="papers">All years ↗</button></div><div class="paper-table">${[2024,2023,2022].map(paperRow).join('')}</div>`}
function bookmarksPage(){return `${heading('Bookmarks')}${bookmarks.length?bookmarks.map(id=>{const [t,i]=id.split('-'),q=questions[t]?.[i];return q?`<article class="result"><span class="pill">${t} · ${q.topic} · DEMO</span><h3>${q.q}</h3><details><summary>Show worked solution</summary><div class="solution">${q.solution}</div></details><button class="text-button" data-remove="${id}">Remove bookmark</button></article>`:''}).join(''):`<div class="empty"><h3>No bookmarks yet.</h3><p>Save questions during practice.</p><button class="btn" data-go="practice">Find a question &nbsp; ↗</button></div>`}`}
function progress(){return `${heading('My progress','Saved in this browser.')}<div class="stats">${stat('◷',history.length,'Sessions completed')}${stat('▤',history.filter(h=>h.track==='PEA').length,'PEA sessions')}${stat('ƒ',history.filter(h=>h.track==='PEB').length,'PEB sessions')}${stat('♧',bookmarks.length,'Saved questions')}</div>${history.length?`<div class="paper-table">${history.slice().reverse().map(h=>`<div class="paper-row"><span class="paper-file">${h.track==='PEA'?'∑':'ƒ'}</span><div class="paper-name">${h.track} demo practice<small>${safe(new Date(h.date).toLocaleString())} · ${h.answered}/${h.total} ${h.track==='PEA'?'answered':'practiced'}</small></div><span class="pill">${h.track==='PEA'?`${h.score}/${h.total} correct`:'SELF-REVIEW'}</span></div>`).join('')}</div>`:`<div class="empty"><h3>No sessions yet.</h3><p>Complete a demo to begin.</p><button class="btn" data-go="practice">Start practicing &nbsp; ↗</button></div>`}`}
function navigate(next){if(test&&!test.done&&next!=='test'){modal(`<h2>Leave this practice session?</h2><p>Current practice will not be saved.</p><div class="dialog-actions"><button class="btn outline" data-close>Keep practicing</button><button class="btn" id="leave-session">Leave session</button></div>`);$('#leave-session').onclick=()=>{closeModal();clearInterval(tick);test=null;navigate(next)};return}page=next;$('#crumb').textContent=({overview:'Overview',papers:'Past year papers',practice:'Mock tests',bookmarks:'Bookmarks',progress:'My progress',analytics:'Analytics',weightage:'Topic weightage',syllabus:'Syllabus',test:'Practice session'})[next];$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===next||(next==='test'&&b.dataset.page==='practice')));$('#content').innerHTML=({overview,papers,practice,bookmarks:bookmarksPage,progress,syllabus,analytics,weightage})[next]?.()||'';if(next==='papers'){renderPapers();$('#search').oninput=renderPapers;$('#paper-track').value=track;renderPapers();$('#paper-track').onchange=()=>{track=$('#paper-track').value;renderPapers()};$('#sort').onchange=renderPapers}if(next==='analytics'){renderAnalytics();$('#analytics-paper').onchange=renderAnalytics;$('#analytics-period').onchange=renderAnalytics}if(next==='weightage'){renderWeightage();$('#weightage-paper').onchange=renderWeightage;$('#weightage-year').onchange=renderWeightage;$('#weightage-kind').onchange=renderWeightage}window.scrollTo(0,0)}
function paperPreview(year,t=track){modal(`<span class="eyebrow">PAST YEAR PAPER WORKSPACE</span><h2 style="margin-top:12px">ISI MSQE ${year} · ${t}</h2><p>Full paper import is pending.</p><p>Try the ${t} demo below.</p><div class="dialog-actions"><button class="btn outline" data-close>Back to library</button><button class="btn" data-launch="${t}">Try ${t} demo &nbsp; ↗</button></div>`)}
function start(t){closeModal();clearInterval(tick);test={track:t,index:0,answers:{},reviewed:{},helpUsed:{},startedAt:Date.now(),tab:'question',end:Date.now()+600000,done:false};$('#crumb').textContent=`${t} practice`;$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page==='practice'));renderTest();window.scrollTo(0,0);if(t==='PEA')tick=setInterval(()=>{if(!test||test.done)return;const left=Math.max(0,Math.ceil((test.end-Date.now())/1000));if($('#timer'))$('#timer').textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;if(left===0){closeModal();finish()}},1000)}
function answered(i){return test.track==='PEB'?Boolean(test.reviewed[i]):test.answers[i]!==undefined}
function renderTest(){const t=test.track,i=test.index,q=questions[t][i],id=`${t}-${i}`,left=Math.max(0,Math.ceil((test.end-Date.now())/1000));$('#content').innerHTML=`${heading(`${t} practice`,'Sample questions')}<div class="test-heading"><span class="pill">${t==='PEA'?'OBJECTIVE':'DESCRIPTIVE'}</span>${t==='PEA'?`<span class="timer" id="timer">${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}</span>`:'<span class="self-review-label">Self-practice</span>'}</div><div class="test-layout"><article class="question-card"><div class="q-meta">${i+1} / ${questions[t].length} · ${q.topic}</div>${t==='PEA'?`<h2>${q.q}</h2>${q.options.map((o,j)=>`<label class="option ${test.answers[i]===j?'selected':''}"><input type="radio" name="answer" value="${j}" ${test.answers[i]===j?'checked':''}><span>${String.fromCharCode(65+j)}.</span> ${o}</label>`).join('')}`:`<div class="tabs question-tabs" role="tablist" aria-label="Question help">${['question','hint','solution'].map(tab=>`<button role="tab" id="tab-${tab}" aria-controls="question-panel" aria-selected="${test.tab===tab}" data-question-tab="${tab}" class="${test.tab===tab?'active':''}">${tab[0].toUpperCase()+tab.slice(1)}</button>`).join('')}</div><div id="question-panel" role="tabpanel" aria-labelledby="tab-${test.tab}">${test.tab==='question'?`<h2>${q.q}</h2>`:`<p class="question-context">${q.q}</p><div class="solution ${test.tab==='hint'?'hint-panel':''}"><b>${test.tab==='hint'?'Hint':'Worked solution'}</b><p>${test.tab==='hint'?q.hint:q.solution}</p></div>`}</div><button class="btn outline mark-practiced" id="mark-practiced" aria-pressed="${answered(i)}">${answered(i)?'✓ Practiced':'Mark as practiced'}</button>`}<div class="q-actions"><button class="btn outline" id="bookmark">${bookmarks.includes(id)?'✓ Saved':'♧ Save'}</button><div><button class="btn outline" id="prev" ${i===0?'disabled':''}>← Back</button> <button class="btn" id="next">${i===questions[t].length-1?(t==='PEA'?'Submit':'Finish'):'Next →'}</button></div></div></article><section class="test-side"><h3>Questions</h3><div class="palette">${questions[t].map((_,j)=>`<button aria-label="Question ${j+1}" data-question="${j}" class="${answered(j)?'answered':''} ${i===j?'current':''}">${j+1}</button>`).join('')}</div><button class="btn" id="submit">${t==='PEA'?'Submit test':'Finish practice'}</button></section></div>`;if(t==='PEA')$$('input[name="answer"]').forEach(el=>el.onchange=()=>{test.answers[i]=Number(el.value);renderTest()});else{$('#mark-practiced').onclick=()=>{test.reviewed[i]=!test.reviewed[i];renderTest()};$$('[data-question-tab]').forEach(b=>b.onclick=()=>{test.tab=b.dataset.questionTab;if(test.tab!=='question'){test.helpUsed[i]??={};test.helpUsed[i][test.tab]=true}renderTest();$(`#tab-${test.tab}`).focus()})}$('#prev').onclick=()=>{if(test.index>0){test.index--;test.tab='question';renderTest()}};$('#next').onclick=()=>{if(i<questions[t].length-1){test.index++;test.tab='question';renderTest()}else confirmSubmit()};$('#submit').onclick=confirmSubmit;$('#bookmark').onclick=()=>{if(bookmarks.includes(id))bookmarks=bookmarks.filter(x=>x!==id);else bookmarks.push(id);save('econprep-bookmarks',bookmarks);renderTest()};$$('[data-question]').forEach(b=>b.onclick=()=>{test.index=Number(b.dataset.question);test.tab='question';renderTest()})}
function confirmSubmit(){const n=questions[test.track].filter((_,i)=>answered(i)).length;modal(`<h2>${test.track==='PEA'?'Submit test?':'Finish practice?'}</h2><p>${n} / ${questions[test.track].length} ${test.track==='PEA'?'answered':'marked as practiced'}.</p><div class="dialog-actions"><button class="btn outline" data-close>Continue</button><button class="btn" id="finish">${test.track==='PEA'?'Submit & review':'Finish & review'}</button></div>`);$('#finish').onclick=()=>{closeModal();finish()}}
function finish(){if(!test||test.done)return;clearInterval(tick);test.done=true;const t=test.track,qs=questions[t],score=t==='PEA'?qs.filter((q,i)=>test.answers[i]===q.answer).length:null;history.push({track:t,date:new Date().toISOString(),score,total:qs.length,answered:qs.filter((_,i)=>answered(i)).length,durationSeconds:Math.max(0,Math.round((Date.now()-test.startedAt)/1000)),details:qs.map((q,i)=>({topic:q.topic,status:t==='PEA'?(test.answers[i]===undefined?'skipped':test.answers[i]===q.answer?'correct':'incorrect'):(answered(i)?'practiced':'unreviewed'),hintUsed:Boolean(test.helpUsed[i]?.hint),solutionViewed:Boolean(test.helpUsed[i]?.solution)}))});save('econprep-history',history);$('#content').innerHTML=`${heading(t==='PEA'?`${score} / ${qs.length} correct`:'Practice complete',t==='PEA'?'Demo scoring: +1 correct, 0 otherwise.':'PEB · Self-review')}<section class="result">${qs.map((q,i)=>`<div class="result-item"><span class="badge-result">${i+1} · ${q.topic}</span><h3>${q.q}</h3>${t==='PEA'?`<p>Your answer: <b>${test.answers[i]===undefined?'Skipped':safe(q.options[test.answers[i]])}</b> · Correct: <b>${safe(q.options[q.answer])}</b></p>`:`<p class="self-review-label">${answered(i)?'✓ Practiced':'Not marked as practiced'}</p><details><summary>Hint</summary><div class="solution hint-panel">${q.hint}</div></details>`}<details><summary>Worked solution</summary><div class="solution">${q.solution}</div></details><button class="text-button" data-save-question="${t}-${i}">${bookmarks.includes(`${t}-${i}`)?'✓ Saved':'♧ Save question'}</button></div>`).join('')}<div class="result-actions"><button class="btn" data-go="practice">Practice again ↗</button><button class="btn outline" data-go="analytics">Analytics</button></div></section>`;window.scrollTo(0,0)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-close'))closeModal();if(b.dataset.page)navigate(b.dataset.page);if(b.dataset.go)navigate(b.dataset.go);if(b.dataset.track){track=b.dataset.track;navigate('practice')}if(b.dataset.switch){track=b.dataset.switch;navigate('practice')}if(b.dataset.year)paperPreview(b.dataset.year);if(b.dataset.preview)paperPreview(b.dataset.paperYear,b.dataset.preview);if(b.dataset.launch)start(b.dataset.launch);if(b.dataset.remove){bookmarks=bookmarks.filter(x=>x!==b.dataset.remove);save('econprep-bookmarks',bookmarks);navigate('bookmarks')}if(b.dataset.saveQuestion){const id=b.dataset.saveQuestion;if(bookmarks.includes(id))bookmarks=bookmarks.filter(x=>x!==id);else bookmarks.push(id);save('econprep-bookmarks',bookmarks);b.textContent=bookmarks.includes(id)?'✓ Bookmarked':'♧ Bookmark question'}if(b.id==='start-demo')start(track);if(b.id==='help')modal(`<h2>A focused beginning.</h2><p>Independent ISI MSQE practice. Progress is saved in this browser.</p><p>Original PDFs and indexed study sets. Solutions are independently derived; source issues are flagged. Not affiliated with ISI.</p><div class="dialog-actions"><button class="btn" data-close>Got it</button></div>`);if(b.id==='pattern')modal(`<h2>Two tracks, one journey.</h2><p><b>PEA</b> provides a multiple-choice practice interface with answer selection, navigation, and scoring.</p><p><b>PEB</b> provides questions, hints and solutions for practice on paper.</p><p>Choose a 30, 60 or 120-minute PEA practice timer. Scoring is unweighted practice scoring, not the official marking scheme.</p><div class="dialog-actions"><button class="btn" data-close>Explore the tracks</button></div>`);if(b.id==='program')modal(`<h2>Start with ISI MSQE.</h2><p>Your current workspace is dedicated to ISI MSQE. GATE, JAM, and CUET PG will have their own preparation spaces in future releases.</p><div class="dialog-actions"><button class="btn" data-close>Back to ISI MSQE</button></div>`)});
$$('nav button').forEach(b=>b.setAttribute('aria-label',b.querySelector('span').textContent));
$('.brand').onclick=e=>{e.preventDefault();navigate('overview')};window.addEventListener('beforeunload',e=>{if(test&&!test.done){e.preventDefault();e.returnValue=''}});navigate('overview');
